contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(
        address ownerAddress,
        address treasuryAddress,
        address newOwnerAddress,
        address recipient,
        uint256 itemPrice,
        uint16 dailyAllowance
    ) public {
        require(ownerAddress != address(0));
        require(treasuryAddress != address(0));
        require(newOwnerAddress != address(0));
        require(recipient != address(0));
        require(recipient != address(this));
        require(itemPrice > 0);
        require(dailyAllowance > 0);

        c.transferOwnership(newOwnerAddress); if (__ESBMC_reverted()) return;
        c.createGameItem(
            "transferableItem",
            "uri",
            false,
            true,
            0,
            itemPrice,
            dailyAllowance
        ); if (__ESBMC_reverted()) return;

        uint256 tokenId = c.uniqueTokensOutstanding() - 1;
        uint256 balBeforeSender = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;
        uint256 balBeforeRecipient = c.balanceOf(recipient, tokenId); if (__ESBMC_reverted()) return;

        c.setApprovalForAll(ownerAddress, true); if (__ESBMC_reverted()) return;

        bool reverted;
        c.safeTransferFrom(address(this), recipient, tokenId, 1, bytes("")); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfterSender = c.balanceOf(address(this), tokenId); if (__ESBMC_reverted()) return;
        uint256 balAfterRecipient = c.balanceOf(recipient, tokenId); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            (
                balBeforeSender >= 1 &&
                balAfterSender + 1 == balBeforeSender &&
                balAfterRecipient == balBeforeRecipient + 1
            )
        );
    }
}

